function promptEnabled(side,prompt){const item=promptOrderEntry(state[side])?.order?.find(x=>(typeof x==='string'?x:x?.identifier)===prompt.identifier);return typeof item==='object'&&typeof item.enabled==='boolean'?item.enabled:prompt.enabled!==false;}
const withoutEnabled=prompt=>{if(!prompt)return prompt;const copy={...prompt};delete copy.enabled;return copy;};
function updateEnabledRowVisual(side,id){if(!["all","dragged","modified"].includes(state.filter[side])){renderList(side);return;}const list=document.querySelector('[data-list="'+side+'"]'),row=rowById(list,id);if(!row){renderList(side);return;}const prompt=byId(side).get(id),enabled=prompt?promptEnabled(side,prompt):true;row.classList.toggle('pcm-row-disabled',!enabled);const sw=row.querySelector('.pcm-switch');if(sw){sw.classList.toggle('pcm-op-enabled',enabled);sw.classList.toggle('pcm-op-disabled',!enabled);sw.setAttribute('aria-checked',String(enabled));sw.title=enabled?'已启用':'已禁用';}const otherSide=side==='old'?'new':'old',otherRow=rowById(document.querySelector('[data-list="'+otherSide+'"]'),id);updateRowBadge(row,id,side);updateRowBadge(otherRow,id,otherSide);updateSummary(side);updateSummary(otherSide);}
function togglePromptEnabled(side,id){const prompt=byId(side).get(id);if(!prompt)return;const next=!promptEnabled(side,prompt),entry=promptOrderEntry(state[side]);if(entry){let item=entry.order.find(x=>(typeof x==='string'?x:x?.identifier)===id);if(typeof item==='string'){const index=entry.order.indexOf(item);item={identifier:id,enabled:next};entry.order[index]=item;}else if(item)item.enabled=next;else entry.order.push({identifier:id,enabled:next});}prompt.enabled=next;state.dirty[side]=true;rebuildCache();updateEnabledRowVisual(side,id);if(state.activeId===id)renderCompare();}
function bindEnabledTags(side){document.querySelectorAll('[data-list="'+side+'"] .pcm-op-enabled,[data-list="'+side+'"] .pcm-op-disabled').forEach(tag=>{const row=tag.closest('.pcm-row');if(row){tag.dataset.toggleEnabled=row.dataset.dragId;tag.dataset.side=side;tag.title='Toggle enabled state';}});}
