function cycleUiTheme(){const i=UI_THEMES.findIndex(x=>x[0]===state.uiTheme);state.uiTheme=UI_THEMES[(i+1)%UI_THEMES.length][0];saveUiTheme(state.uiTheme);applyUiTheme();const b=document.querySelector('[data-theme-toggle]');if(b)b.innerHTML=UI_THEME_ICONS[state.uiTheme]||'';}
function installHeaderToggles(){const header=document.querySelector('.pcm-header');if(!header)return;if(!header.querySelector('[data-theme-toggle]')){const tbtn=el('button','menu_button pcm-theme-toggle');tbtn.type='button';tbtn.dataset.themeToggle='';tbtn.innerHTML=UI_THEME_ICONS[state.uiTheme]||'';tbtn.title='切换插件配色：叶子=自适应酒馆 / 太阳=日间 / 月亮=夜间（Gruvbox Dark），选择会自动记住';tbtn.addEventListener('click',cycleUiTheme);header.insertBefore(tbtn,header.lastElementChild);}if(!header.querySelector('[data-free-select]')){const label=el('label','pcm-free-select'),input=el('input');input.type='checkbox';input.dataset.freeSelect='';input.checked=state.freeSelect.enabled;label.append(input,el('span','', '自由选择'));header.insertBefore(label,header.lastElementChild);}if(!header.querySelector('[data-ignore-whitespace]')){const label=el('label','pcm-free-select'),input=el('input');input.type='checkbox';input.dataset.ignoreWhitespace='';input.checked=state.ignoreWhitespace;label.title='忽略仅空白（空格/换行/缩进）不同的差异';label.append(input,el('span','', '忽略空白'));header.insertBefore(label,header.lastElementChild);}if(!header.querySelector('[data-show-similarity]')){const label=el('label','pcm-free-select'),input=el('input');input.type='checkbox';input.dataset.showSimilarity='';input.checked=state.showSimilarity;label.title='同名已修改条目显示正文差异百分比，差异小可放心忽略、差异大重点核对是否为自己的魔改或作者的重要更新';label.append(input,el('span','', '差异程度'));header.insertBefore(label,header.lastElementChild);}if(!header.querySelector('[data-sync-scroll]')){const label=el('label','pcm-free-select'),input=el('input');input.type='checkbox';input.dataset.syncScroll='';input.checked=state.syncScroll;label.title='开启后左右两个列表按渲染顺序对齐滚动，便于逐条对比同一条目';label.append(input,el('span','', '同步滚动'));header.insertBefore(label,header.lastElementChild);}}
/* 全文档 subtree 观察已移除（酒馆流式消息每次 DOM 变动都会触发，拖累宿主页面）：shell() 挂载后直接调 installHeaderToggles()。 */
function onHeaderToggleChange(event){if(event.target.matches?.('[data-free-select]'))setFreeSelect(event.target.checked);if(event.target.matches?.('[data-ignore-whitespace]'))setIgnoreWhitespace(event.target.checked);if(event.target.matches?.('[data-show-similarity]'))setShowSimilarity(event.target.checked);if(event.target.matches?.('[data-sync-scroll]'))setSyncScroll(event.target.checked);if(event.target.matches?.('[data-toggle-diff]')){state.showDiff=event.target.checked;saveUiPrefs();if(state.freeSelect.enabled&&state.freeSelect.oldId&&state.freeSelect.newId)renderFreeCompare();else renderCompare();}}
function onFreeSelectClick(event){if(!state.freeSelect.enabled)return;const button=event.target.closest?.('[data-open][data-side]');if(button&&selectFreePrompt(button.dataset.side,button.dataset.open)){event.preventDefault();event.stopImmediatePropagation();}}
function setFreeSelect(enabled){state.freeSelect={enabled,oldId:null,newId:null};state.activeId=null;saveUiPrefs();hideCompare();renderAll();pcmToastr.info(enabled?'请先选择旧版条目，再选择新版条目':'已关闭自由选择');}
function setIgnoreWhitespace(enabled){state.ignoreWhitespace=enabled;saveUiPrefs();rebuildCache();renderAll();pcmToastr.info(enabled?'已忽略仅空白（空格/换行/缩进）不同的差异':'已恢复逐字精确比对');}
