/* 字符级 diff：先做行级比对，再把相邻「删除块+新增块」配对成行对，对每对做行内字符级 Myers diff，只高亮真正变化的字符而非整行标红。公共前后缀裁剪 + Myers O(ND)，相似文本近零分配；多重阈值保护（乘积/总长度/编辑距离上限）防超长文本在手机端内存膨胀，超限自动退化为整段标记。 */
const LINE_DIFF_LIMIT=200000,CHAR_DIFF_LIMIT=40000,DIFF_MAX_SEQ=4000,MYERS_MAX_D=800;
function myers(a,b){const n=a.length,m=b.length;if(!n)return b.map(x=>['+',x]);if(!m)return a.map(x=>['-',x]);const off=n+m,W=2*off+1;let v=new Int32Array(W);const trace=[];let D=-1;for(let d=0;d<=off;d++){if(d>MYERS_MAX_D)return null;trace.push(v);const nv=v.slice();for(let k=-d;k<=d;k+=2){let x=(k===-d||(k!==d&&nv[k-1+off]<nv[k+1+off]))?nv[k+1+off]:nv[k-1+off]+1,y=x-k;while(x<n&&y<m&&a[x]===b[y]){x++;y++;}nv[k+off]=x;if(x>=n&&y>=m){D=d;break;}}v=nv;if(D>=0)break;}const ops=[];let x=n,y=m;for(let d=D;d>0;d--){const vv=trace[d],k=x-y,pk=(k===-d||(k!==d&&vv[k-1+off]<vv[k+1+off]))?k+1:k-1,px=vv[pk+off],py=px-pk;while(x>px&&y>py){ops.push([' ',a[x-1]]);x--;y--;}if(x===px){ops.push(['+',b[y-1]]);y--;}else{ops.push(['-',a[x-1]]);x--;}}while(x>0&&y>0){ops.push([' ',a[x-1]]);x--;y--;}ops.reverse();return ops;}
function diffSeq(a,b,limit){let s=0;const min=Math.min(a.length,b.length);while(s<min&&a[s]===b[s])s++;let ea=a.length,eb=b.length;while(ea>s&&eb>s&&a[ea-1]===b[eb-1]){ea--;eb--;}const ops=[];for(let i=0;i<s;i++)ops.push([' ',a[i]]);const ma=ea-s,mb=eb-s;let mid=null;if(ma>0&&mb>0&&ma*mb<=limit&&ma+mb<=DIFF_MAX_SEQ)mid=myers(a.slice(s,ea),b.slice(s,eb));if(mid)for(let i=0;i<mid.length;i++)ops.push(mid[i]);else{for(let i=s;i<ea;i++)ops.push(['-',a[i]]);for(let j=s;j<eb;j++)ops.push(['+',b[j]]);}for(let i=ea;i<a.length;i++)ops.push([' ',a[i]]);return ops;}
