function paintBackdrop(bd,rows,side){let i=0;const kids=bd.children;for(let r=0;r<rows.length;r++){const row=rows[r];if(side==='old'&&row.t==='+')continue;if(side==='new'&&row.t==='-')continue;let node=kids[i];if(!node){node=el('span');bd.append(node);node._k=null;}let key=row.t;for(let q=0;q<row.segs.length;q++){const s=row.segs[q];key+=''+s.t+''+s.text;}if(node._k!==key){node.className=row.t===' '?'ctx':row.t==='-'?'del':'add';const frag=document.createDocumentFragment();for(let q=0;q<row.segs.length;q++){const s=row.segs[q];if(side==='old'&&s.t==='+')continue;if(side==='new'&&s.t==='-')continue;if(s.t===' ')frag.append(document.createTextNode(s.text));else{const sp=el('span',s.t==='-'?'d':'a');sp.textContent=s.text;frag.append(sp);}}node.replaceChildren(frag);node._k=key;}i++;}while(kids.length>i)bd.lastChild.remove();}
function setupLiveDiff(detail){const areas=detail.querySelectorAll('.pcm-live-area');if(areas.length<2)return;const oldArea=areas[0],newArea=areas[1],oldBd=oldArea.previousElementSibling,newBd=newArea.previousElementSibling;if(!oldBd||!newBd)return;const align=(a,b)=>{const cs=getComputedStyle(a);b.style.fontFamily=cs.fontFamily;b.style.fontSize=cs.fontSize;b.style.lineHeight=cs.lineHeight;b.style.letterSpacing=cs.letterSpacing;b.style.paddingTop=(parseFloat(cs.paddingTop)+parseFloat(cs.borderTopWidth))+'px';b.style.paddingRight=(parseFloat(cs.paddingRight)+parseFloat(cs.borderRightWidth))+'px';b.style.paddingBottom=(parseFloat(cs.paddingBottom)+parseFloat(cs.borderBottomWidth))+'px';b.style.paddingLeft=(parseFloat(cs.paddingLeft)+parseFloat(cs.borderLeftWidth))+'px';};align(oldArea,oldBd);align(newArea,newBd);const update=()=>{const rows=buildRows(diffLines(oldArea.value,newArea.value));paintBackdrop(oldBd,rows,'old');paintBackdrop(newBd,rows,'new');};let timer=null;const deb=()=>{clearTimeout(timer);timer=setTimeout(update,250);};oldArea.addEventListener('input',deb);newArea.addEventListener('input',deb);const sync=(a,b)=>{b.scrollTop=a.scrollTop;b.scrollLeft=a.scrollLeft;};oldArea.addEventListener('scroll',()=>sync(oldArea,oldBd));newArea.addEventListener('scroll',()=>sync(newArea,newBd));if(window.requestIdleCallback)requestIdleCallback(update,{timeout:200});else setTimeout(update,0);}
