let dropMarker=null,dropClass='',dropEndList=null;function clearDropMarker(){if(dropMarker&&dropClass)dropMarker.classList.remove(dropClass);if(dropEndList){dropEndList.classList.remove('pcm-drop-end');dropEndList.classList.remove('pcm-group-drop');}dropMarker=null;dropClass='';dropEndList=null;}function nextRenderedRowId(row){const direct=row.nextElementSibling;if(direct?.matches('.pcm-row'))return direct.dataset.dragId;let sibling=row.closest('.pcm-group')?.nextElementSibling||direct;while(sibling){if(sibling.matches?.('.pcm-row'))return sibling.dataset.dragId;const nested=sibling.querySelector?.('.pcm-row');if(nested)return nested.dataset.dragId;sibling=sibling.nextElementSibling;}return null;}function markDropTarget(row,event){const rect=row.getBoundingClientRect(),after=event.clientY>rect.top+rect.height/2,nextClass=after?'pcm-drop-after':'pcm-drop-before';if(dropMarker!==row||dropClass!==nextClass){clearDropMarker();row.classList.add(nextClass);dropMarker=row;dropClass=nextClass;}return after?nextRenderedRowId(row):row.dataset.dragId;}function onDragStart(event){if(touchContacts>0||pointerDrag){if(pointerDrag)cleanupPointerDrag();event.preventDefault();return;}const row=event.target.closest('.pcm-row');if(!row)return;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',JSON.stringify({id:row.dataset.dragId,side:row.dataset.dragSide}));row.classList.add('pcm-dragging');pcmLock();html5DragLock=true;startDragAutoScroll();}function groupIdForRow(row){const group=row?.closest('.pcm-group');return group?.dataset.groupId||null;}
function applyDropGroup(side,id,groupId){const groupState=getBaiBaiGroupState(state[side]);if(!groupState&&!groupId)return;const ensured=ensureBaiBaiGroupState(state[side]);if(groupId)ensured.prompts[id]={groupId:String(groupId)};else delete ensured.prompts[id];}
function onDragOver(event){html5DragPointer={x:event.clientX,y:event.clientY,t:performance.now()};const list=event.target.closest('.pcm-list');if(!list)return;event.preventDefault();const row=event.target.closest('.pcm-row');if(row){markDropTarget(row,event);return;}const groupHead=event.target.closest('.pcm-group-head'),group=groupHead?.closest('.pcm-group');if(group?.dataset.groupId){clearDropMarker();group.classList.add('pcm-group-drop');dropEndList=group;return;}if(dropEndList!==list){clearDropMarker();list.classList.add('pcm-drop-end');dropEndList=list;}}function onDrop(event){stopDragAutoScroll();const list=event.target.closest('.pcm-list');if(!list)return;event.preventDefault();const row=event.target.closest('.pcm-row');if(row){try{const data=JSON.parse(event.dataTransfer.getData('text/plain')),beforeId=markDropTarget(row,event),targetSide=list.dataset.list,targetGroupId=groupIdForRow(row);clearDropMarker();movePrompt(data.side,targetSide,data.id,beforeId);applyDropGroup(targetSide,data.id,targetGroupId);rebuildCache();renderList(targetSide);}catch{clearDropMarker();}return;}const groupHead=event.target.closest('.pcm-group-head'),group=groupHead?.closest('.pcm-group');if(group?.dataset.groupId){try{const data=JSON.parse(event.dataTransfer.getData('text/plain'));group.classList.remove('pcm-group-drop');assignPromptToGroup(data.side,group.dataset.groupSide,data.id,group.dataset.groupId);}catch{}clearDropMarker();return;}try{const data=JSON.parse(event.dataTransfer.getData('text/plain'));clearDropMarker();movePrompt(data.side,list.dataset.list,data.id,null);}catch{clearDropMarker();}}
function onDragEnd(event){if(event.target instanceof Element)event.target.closest('.pcm-row')?.classList.remove('pcm-dragging');clearDropMarker();stopDragAutoScroll();if(html5DragLock){html5DragLock=false;pcmUnlock();}}
async function tavernPresetCandidates(){const candidates=new Map(),add=(name,value)=>{if(value&&Array.isArray(value.prompts))candidates.set(String(name||'未命名预设'),value);};try{const module=await import('/scripts/openai.js'),names=module.openai_setting_names||{},settings=module.openai_settings||[];if(Array.isArray(names))names.forEach((name,index)=>add(name,settings[index]));else Object.entries(names).forEach(([name,index])=>add(name,settings[Number(index)]));}catch(error){console.warn('[preset-compare-migrator] Failed to import openai preset module',error);}return candidates;}
async function pullTavernPreset(){const candidates=await tavernPresetCandidates();if(!candidates.size){pcmToastr.warning('未能读取 Chat Completion/OpenAI 预设。','未找到酒馆预设');return;}tavernPresetPickerData=candidates;let picker=document.querySelector('[data-tavern-picker]');if(!picker){picker=el('section','pcm-picker');picker.dataset.tavernPicker='';const panel=el('div','pcm-picker-panel'),head=el('header','pcm-picker-head');head.append(el('h3','', '选择酒馆预设'),btn('×','close-picker','pcm-collapse'));panel.append(head);const list=el('div','pcm-picker-list');list.dataset.pickerList='';panel.append(list);picker.append(panel);document.getElementById(APP_ID+'-dialog').append(picker);}const list=picker.querySelector('[data-picker-list]');list.replaceChildren();for(const [name,preset] of candidates){const item=btn(name,'choose-tavern','pcm-picker-item');item.dataset.presetName=name;item.append(el('small','',preset.prompts.length+' 个条目'));list.append(item);}picker.classList.add('open');}
function chooseTavernPreset(name){const preset=tavernPresetPickerData.get(name);if(!preset)return;state.old=validate(clone(preset));state.oldName=name+'.json';state.tavernSource.old=name;state.dirty.old=false;state.activeId=null;document.querySelector('[data-tavern-picker]')?.classList.remove('open');hideCompare();rebuildCache();renderAll(false);pcmToastr.success('已从酒馆载入：'+name);}
function snapshotGroupChange(side){const preset=state[side];pushUndo({type:'move',side,promptOrder:preset.prompts.map(p=>p.identifier),prompts:new Map(preset.prompts.map(p=>[p.identifier,p])),promptOrderData:clone(preset.prompt_order),extensionsBefore:clone(preset.extensions),draggedBefore:[...state.dragged[side]]});}
function deletePrompt(side,id){const preset=state[side];if(!preset)return;if(!confirm('确定从'+(side==='old'?'旧版':'新版')+'删除该条目吗？（可撤回）'))return;snapshotGroupChange(side);preset.prompts=preset.prompts.filter(p=>p.identifier!==id);const order=orderArray(preset),oi=order.findIndex(x=>(typeof x==='string'?x:x?.identifier)===id);if(oi>=0)order.splice(oi,1);if(state.activeId===id){state.activeId=null;state.activeSide=null;hideCompare();}state.dirty[side]=true;rebuildCache();renderAll();pcmToastr.success('已删除条目');}
function duplicatePrompt(side,id){const preset=state[side],prompt=byId(side).get(id);if(!preset||!prompt)return;snapshotGroupChange(side);const copy=clone(prompt);copy.identifier=crypto.randomUUID();copy.name=(prompt.name||'(未命名)')+' 副本';const idx=preset.prompts.findIndex(p=>p.identifier===id);preset.prompts.splice(idx<0?preset.prompts.length:idx+1,0,copy);const order=orderArray(preset),oi=order.findIndex(x=>(typeof x==='string'?x:x?.identifier)===id);order.splice(oi<0?order.length:oi+1,0,{identifier:copy.identifier,enabled:prompt.enabled!==false});const srcGroups=getBaiBaiGroupState(preset),srcGid=srcGroups?.prompts?.[id]?.groupId;if(srcGid&&Array.isArray(srcGroups.groups)&&srcGroups.groups.some(g=>String(g.id)===String(srcGid)))ensureBaiBaiGroupState(preset).prompts[copy.identifier]={groupId:String(srcGid)};state.dirty[side]=true;rebuildCache();renderAll();pcmToastr.success('已复制条目');}
function newGroup(side){const preset=state[side];if(!preset)return;const name=prompt('输入分组名称','新分组');if(!name)return;snapshotGroupChange(side);const groupState=ensureBaiBaiGroupState(preset);const groupId=crypto.randomUUID();groupState.groups.push({id:groupId,name,order:groupState.groups.length,collapsed:false,enabled:true});state.grouping={side,groupId};state.dirty[side]=true;renderList(side);}
function renameGroup(side,id){const groupState=getBaiBaiGroupState(state[side]),group=groupState?.groups?.find(g=>String(g.id)===String(id));if(!group)return;const name=prompt('输入新的分组名称',group.name||'');if(!name)return;snapshotGroupChange(side);group.name=name;state.dirty[side]=true;renderList(side);}
function deleteGroup(side,id){const groupState=getBaiBaiGroupState(state[side]);if(!groupState||!confirm('删除分组？组内条目会变为未分组，不会被删除。'))return;snapshotGroupChange(side);groupState.groups=groupState.groups.filter(g=>String(g.id)!==String(id));for(const [promptId,meta] of Object.entries(groupState.prompts||{}))if(String(meta?.groupId)===String(id))delete groupState.prompts[promptId];state.dirty[side]=true;renderList(side);}
function assignPromptToGroup(sourceSide,targetSide,id,groupId){const source=state[sourceSide],target=state[targetSide],prompt=byId(sourceSide).get(id);if(!source||!target||!prompt)return;const groupState=ensureBaiBaiGroupState(target);if(!groupState.groups.some(g=>String(g.id)===String(groupId)))return;snapshotGroupChange(targetSide);if(!byId(targetSide).has(id)){const ord=state.cache.ordered[targetSide];let last=-1;for(let i=0;i<ord.length;i++){const gid2=groupState.prompts?.[ord[i].identifier]?.groupId;if(gid2&&String(gid2)===String(groupId))last=i;}const beforeId=last>=0&&last+1<ord.length?ord[last+1].identifier:null;movePrompt(sourceSide,targetSide,id,beforeId);}groupState.prompts[id]={groupId:String(groupId)};state.dirty[targetSide]=true;rebuildCache();renderList(targetSide);}
function togglePromptGroup(side,id){const grouping=state.grouping;if(grouping.side!==side||!grouping.groupId)return false;const groupState=ensureBaiBaiGroupState(state[side]),current=groupState.prompts?.[id]?.groupId;snapshotGroupChange(side);if(String(current||'')===String(grouping.groupId))delete groupState.prompts[id];else groupState.prompts[id]={groupId:String(grouping.groupId)};state.dirty[side]=true;renderList(side);return true;}
function finishGrouping(){state.grouping={side:null,groupId:null};renderAll();}
function onClick(event){if(performance.now()<suppressClickUntil)return;const target=event.target.closest('button');if(!target)return;const action=target.dataset.action;const groupElement=target.closest('.pcm-group');const groupId=groupElement?.dataset.groupId;const groupSide=groupElement?.dataset.groupSide||target.dataset.side;if(action==='submit-version'){document.querySelector('.pcm-inline-form[data-side="'+target.dataset.side+'"]')?.requestSubmit();}if(action==='choose-tavern')chooseTavernPreset(target.dataset.presetName);if(action==='close-picker')document.querySelector('[data-tavern-picker]')?.classList.remove('open');if(action==='new-group')newGroup(target.dataset.side);if(action==='rename-group')renameGroup(groupSide,groupId);if(action==='delete-group')deleteGroup(groupSide,groupId);if(action==='finish-group')finishGrouping();if(action==='toggle-uninjected'){const side=target.dataset.side;state.unInjectedCollapsed[side]=!state.unInjectedCollapsed[side];renderList(side);}if(action==='toggle-group'){const gk=target.dataset.groupKey;if(gk){state.groupCollapsed[gk]=!state.groupCollapsed[gk];renderList(target.dataset.side);}}if(action==='close'){if(typeof event.currentTarget.close==='function')event.currentTarget.close();else event.currentTarget.removeAttribute('open');}if(action==='export')exportPreset(target.dataset.side);if(action==='save-tavern')saveSideToTavern(target.dataset.side);if(action==='pull-tavern')pullTavernPreset();if(action==='save-project')saveProject();if(action==='save-changes'){if(state.projectId)saveProject(document.querySelector('[data-project-name]')?.value.trim());else saveProject();}if(action==='load-project'){const id=document.querySelector('[data-project-select]')?.value;if(id)loadProject(id);}if(action==='delete-project'){const id=document.querySelector('[data-project-select]')?.value;if(id)deleteProject(id);}if(action==='undo')undoLast();if(action==='collapse'){state.activeId=null;state.activeSide=null;if(state.freeSelect.enabled){state.freeSelect={enabled:true,oldId:null,newId:null};markFreeSelection();}hideCompare();renderAll();}if(action==='migrate')migrate(target.dataset.side);if(action==='duplicate-prompt')duplicatePrompt(target.dataset.side,target.dataset.id);if(action==='delete-prompt')deletePrompt(target.dataset.side,target.dataset.id);if(target.dataset.open){if(togglePromptGroup(target.dataset.side,target.dataset.open))return;state.activeId=target.dataset.open;state.activeSide=target.dataset.side;renderAll();}}
function onChange(event){if(event.target.dataset.file&&event.target.files[0])loadFile(event.target.dataset.file,event.target.files[0]);if(event.target.dataset.filter){const side=event.target.dataset.filter;state.filter[side]=event.target.value;renderList(side);}}
const searchTimers={old:null,new:null};
function onInput(event){if(event.target.dataset.search){const side=event.target.dataset.search;state.query[side]=event.target.value;clearTimeout(searchTimers[side]);searchTimers[side]=setTimeout(()=>renderList(side),150);}}
function openDialogSafe(dialog){applyUiTheme();try{if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}catch(error){console.error('[preset-compare-migrator] open failed',error);dialog.setAttribute('open','');}}
function addMenu(){const menu=document.getElementById('extensionsMenu');if(!menu||document.getElementById(APP_ID+'-button'))return false;const entry=el('div','list-group-item flex-container flexGap5 interactable');entry.id=APP_ID+'-button';entry.tabIndex=0;entry.append(el('span','fa-solid fa-code-compare'),el('span','',APP_TITLE));entry.addEventListener('click',()=>{try{const d=shell();openDialogSafe(d);restorePanelState(d);}catch(error){console.error('[preset-compare-migrator] init failed',error);pcmToastr.error(error.message,APP_TITLE+'启动失败');}});menu.append(entry);return true;}
jQuery(()=>{loadUiPrefs();watchTavernPresetEvents();if(!addMenu()){const observer=new MutationObserver(()=>{if(addMenu())observer.disconnect();});observer.observe(document.body,{childList:true,subtree:true});}});
